public class InsertStatementBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String statement(Object row) {
        try {
            return InsertStatementBuilder.buildInsert(row);
        } catch (Throwable t) {
            return t.getClass().getSimpleName() + ": " + t.getMessage();
        }
    }

    public static void main(String[] args) {
        check("a two-column row, unannotated field skipped",
                "INSERT INTO users (user_id, full_name) VALUES (1, 'Ada')",
                statement(new UserRow(1, "Ada", 9)));
        check("a three-column row from another table",
                "INSERT INTO products (sku, price_cents, note) VALUES ('A1', 250, 'nice')",
                statement(new ProductRow("A1", 250, "nice")));
        check("a null value becomes NULL, not quoted",
                "INSERT INTO products (sku, price_cents, note) VALUES ('A2', 0, NULL)",
                statement(new ProductRow("A2", 0, null)));
        check("an empty String is still quoted",
                "INSERT INTO users (user_id, full_name) VALUES (42, '')",
                statement(new UserRow(42, "", 0)));
        check("a class without @Table", "IllegalArgumentException: no @Table on LooseRow",
                statement(new LooseRow(5)));
        check("the unannotated field changes nothing", true,
                statement(new UserRow(1, "Ada", 9)).equals(statement(new UserRow(1, "Ada", 77))));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

