public class InsertStatementBuilder {

    public static String buildInsert(Object row) {
        Table table = row.getClass().getAnnotation(Table.class);
        if (table == null) {
            throw new IllegalArgumentException("no @Table on " + row.getClass().getSimpleName());
        }
        StringBuilder columns = new StringBuilder();
        StringBuilder values = new StringBuilder();
        for (Field field : row.getClass().getDeclaredFields()) {
            Column column = field.getAnnotation(Column.class);
            if (column == null) {
                continue;
            }
            field.setAccessible(true);
            Object value;
            try {
                value = field.get(row);
            } catch (IllegalAccessException e) {
                value = null;
            }
            if (columns.length() > 0) {
                columns.append(", ");
                values.append(", ");
            }
            columns.append(column.name());
            values.append(format(value));
        }
        return "INSERT INTO " + table.name() + " (" + columns + ") VALUES (" + values + ")";
    }

    private static String format(Object value) {
        if (value == null) {
            return "NULL";
        }
        if (value instanceof String) {
            return "'" + value + "'";
        }
        return String.valueOf(value);
    }
}
